if (!int.TryParse((Console.ReadLine() ?? "").Trim(), out var threshold) || threshold < 1 || threshold > 100) Environment.Exit(1);
var readings = (Console.ReadLine() ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);
if (readings.Length > 50) Environment.Exit(1);
var monitor = new TemperatureMonitor(threshold);
var alerts = new List<int>();
monitor.Alert += (_, args) => alerts.Add(args.Value);
foreach (var token in readings)
{
    if (!int.TryParse(token, out var value)) Environment.Exit(1);
    monitor.Observe(value);
}
Console.WriteLine($"alerts={alerts.Count} first={(alerts.Count > 0 ? alerts[0].ToString() : "none")} max={(alerts.Count > 0 ? alerts.Max().ToString() : "none")}");

sealed class AlertArgs : EventArgs
{
    public int Value { get; init; }
}

sealed class TemperatureMonitor
{
    private readonly int _threshold;

    public TemperatureMonitor(int threshold) => _threshold = threshold;

    public event EventHandler<AlertArgs>? Alert;

    public void Observe(int value)
    {
        if (value >= _threshold)
        {
            Alert?.Invoke(this, new AlertArgs { Value = value });
        }
    }
}
